 wal:['PostgreSQL · Write-ahead logging','https://www.postgresql.org/docs/current/wal-intro.html'],
 kafka:['Apache Kafka · Design and delivery semantics','https://kafka.apache.org/41/design/design/'],
 outbox:['AWS · Transactional outbox','https://docs.aws.amazon.com/prescriptive-guidance/latest/cloud-design-patterns/transactional-outbox.html'],
 retry:['AWS Builders’ Library · Timeouts, retries, and jitter','https://aws.amazon.com/builders-library/timeouts-retries-and-backoff-with-jitter/'],
