 telemetry:['OpenTelemetry · Signals','https://opentelemetry.io/docs/concepts/signals/'],
 restore:['PostgreSQL · Point-in-time recovery','https://www.postgresql.org/docs/current/continuous-archiving.html'],
 security:['OWASP · Object-level authorization','https://api-security.owasp.org/editions/2023/en/0xa1-broken-object-level-authorization/'],
 http:['IETF · HTTP semantics','https://www.rfc-editor.org/rfc/rfc9110'],
